def constraint_fun(solution):
    constrain= []
    # Check that each city is visited only once.
    for i in range(len(solution)):
        for j in range(i + 1, len(solution)):
            if solution[i] == solution[j]:
                constrain.append(1)
            else:
                constrain.append(0)

    return (sum(constrain), sum(solution) - 6)
